import {GameState} from '../core/game-state.js';import {ActionRegistry} from '../core/action-registry.js';import {installCombatActions} from '../combat/action-catalog.js';import {BattleStore} from '../ui/store.js';import {ActionController} from '../ui/action-controller.js';export async function createClient({weapons,state=new GameState(1),rng=Math.random}={}){const registry=installCombatActions(new ActionRegistry(),weapons);const store=new BattleStore(state);const actions=new ActionController({registry,state,store,rng});return{state,registry,store,actions};}